// Üretilen dosya: tool/ozgun/uret.py. Doğa · Hayvanlarda iletişim, yön bulma, göç, kış-yaz uykusu, kamuflaj ve mimikri stratejileri (ekolokasyon, feromon, arı dansı, Bates ve Müller mimikrisi) (kolay).
const ozNature18Kolay = <(String, String, List<String>, String)>[
  ('Yarasaların ve yunusların karanlık ya da bulanık ortamlarda çevrelerini algılamak için yüksek frekanslı ses dalgaları gönderip yankısını dinlemesi olayı nasıl adlandırılır?', 'Ekolokasyon', ['Manyetoresepsiyon', 'Biyolüminesans', 'Termoresepsiyon'], 'Canlıların çıkardıkları ses dalgalarının nesnelere çarpıp geri dönen yankılarını analiz ederek mesafe ve yön belirlemesine ekolokasyon (yankı ile yer bulma) denir.'),
  ('Böcekçil yarasaların ekolokasyon sırasında kullandığı ve insan kulağının işitme sınırının üzerinde yer alan ses dalgaları hangi gruba girer?', 'Ultrasonik ses', ['İnfrasonik ses', 'Elektromanyetik dalga', 'Sismik yüzey dalgası'], 'İnsan kulağının üst işitme sınırı olan 20 kHz\'in üzerindeki yüksek frekanslı ses dalgalarına ultrasonik ses (ultrasaund) adı verilir.'),
  ('Mısır meyve yarasası (Rousettus) gibi dil şaklatmasıyla ekolokasyon yapan türler dışında, mikro yarasaların büyük çoğunluğu ultrasonik seslerini hangi organlarıyla üretir?', 'Gırtlak', ['Burun boşluğu keseleri', 'Kanat zarı titreşimleri', 'Yutak altı hava kesesi'], 'Böcekçil yarasaların neredeyse tamamı ultrasonik çağrılarını son derece özelleşmiş gırtlak (larinks) kasları ve ses telleri yardımıyla üretir; Rousettus ise dil şaklatır.'),
  ('Dişli balinalar ve yunuslarda alnın ön kısmında bulunan, ekolokasyon tıkırtılarını odaklayarak suya ileten yağ dokusu bakımından zengin organa ne ad verilir?', 'Melon', ['Rostrum', 'Spirakulum', 'Timpani'], 'Yunusların alın bölgesindeki "melon" adı verilen özel lipit (yağ) yapılı akustik mercek, üretilen ses dalgalarını dar bir demet halinde suya odaklar.'),
  ('Şişe burunlu yunusların her bireyinin yaşamının ilk dönemlerinde geliştirdiği ve grup içinde birbirlerini sesle tanımalarını sağlayan kendine özgü ıslık örüntüsüne ne ad verilir?', 'İmza ıslığı (signature whistle)', ['Ekolokasyon vızıltısı (terminal buzz)', 'Rezonans korosu (chorus call)', 'Bölgesel lehçe (dialect click)'], 'Şişe burunlu yunuslar tıpkı insanların isimleri gibi işlev gören, bireye özgü frekans eğrisine sahip "imza ıslıkları" ile birbirlerine seslenirler.'),
  ('Aynı türe ait bireyler arasında iletişim kurmak amacıyla vücut dışına salgılanan ve alıcı bireyde belirli davranışsal ya da fizyolojik tepkiler uyandıran uçucu veya sıvı kimyasal maddelere ne ad verilir?', 'Feromon', ['Hormon', 'Enzim', 'Nörotransmitter'], 'Hormonlar vücut içinde kanla taşınırken, feromonlar (ektohormonlar) dış ortama bırakılarak aynı türün diğer bireylerinde tepki oluşturan kimyasal habercilerdir.'),
  ('Besin kaynağı bulan öncü bir işçi karıncanın yuvasına dönerken diğer işçilerin aynı yolu izlemesi için karın ucunu yere değdirerek bıraktığı kimyasal işarete ne ad verilir?', 'İz feromonu', ['Alarm feromonu', 'Kraliçe baskılama feromonu', 'Agregasyon (toplanma) feromonu'], 'Karıncaların ve termitlerin yuva ile besin arasında yol işaretlemek için zemine bıraktıkları uçucu kimyasal salgılara iz feromonu (trail pheromone) denir.'),
  ('İpek böceği güvesi (Bombyx mori) üzerinde yapılan klasik araştırmalarda, dişi güvenin erkekleri kilometrelerce uzaktan çekmek için salgıladığı ve ilk kez kimyasal yapısı aydınlatılan eşey feromonu hangisidir?', 'Bombikol', ['sitronellal', 'Formik asit', 'Lusikiferin'], 'Adolf Butenandt ve ekibi 1959 yılında dişi ipek böceği güvelerinden "bombikol" adlı ilk böcek eşey feromonunu izole edip kimyasal yapısını tanımlamıştır.'),
  ('Bir bal arısı veya yaban arısı yuvasına saldırıldığında sokan bireyin iğne kesesinden yayılan ve diğer işçileri hızla saldırgana yönelten muz kokulu (izoamil asetat içeren) kimyasal hangi feromon tipidir?', 'Alarm feromonu', ['İz feromonu', 'Eşey feromonu', 'Bölge işaretleme feromonu'], 'Sosyal böceklerde tehlike anında salgılanıp kolonide savunma, kaçma veya toplu saldırı tepkisi başlatan uçucu kimyasallara alarm feromonu denir.'),
  ('Bal arılarının besin kaynaklarının yerini kovan arkadaşlarına "sallanma dansı" (waggle dance) ile bildirdiğini keşfederek 1973 Nobel Fizyoloji veya Tıp Ödülü\'nü paylaşan bilim insanı kimdir?', 'Karl von Frisch', ['Konrad Lorenz', 'Nikolaas Tinbergen', 'Ivan Pavlov'], 'Avusturyalı etolog Karl von Frisch, bal arılarının renk görme yetisini ve ünlü sallanma dansı (waggle dance) dilini çözümleyerek 1973\'te Lorenz ve Tinbergen ile Nobel almıştır.'),
  ('Bal arılarının petek üzerinde 8 rakamına benzer bir yörünge çizip ortadaki düz hatta karınlarını hızla titreterek yaptıkları "sallanma dansı" (waggle dance) esas olarak hangi besin kaynakları için uygulanır?', 'Kovandan uzak mesafede (genellikle 100 metreden ileride) bulunan zengin nektar veya polen kaynakları için', ['Kovanın hemen giriş deliğinin bir-iki santimetre önünde duran su damlacıkları için', 'Yalnızca kovanın içindeki petek gözlerinde depolanmış olan olgunlaşmış bal stokları için', 'Çiçeklerin tamamen kuruduğu kış ortasında kovan sıcaklığını düşürmek için'], 'Kovandan yaklaşık 50-100 metreden daha uzak kaynaklar için yön ve mesafe bilgisi içeren 8 şeklindeki sallanma dansı (waggle dance) yapılır.'),
  ('Karl von Frisch\'in bulgularına göre bal arılarının kovana çok yakın (yaklaşık 50 metreden daha yakın) bir besin kaynağı bulduklarında yaptıkları "dairesel dans" (round dance) kovan arkadaşlarına hangi bilgiyi verir?', 'Kovanın yakın çevresinde besin bulunduğunu ve dansçının üzerindeki çiçek kokusunun aranması gerektiğini, ancak kesin yön belirtmediğini', ['Besinin kovandan tam 5 kilometre kuzeydoğuda bir dere yatağında bulunduğunu', 'Koloninin mevcut kovanı terk edip yeni bir ağaç kovuğuna oğul vermesi gerektiğini', 'Yakındaki çiçeklerin yırtıcı eşek arıları tarafından tamamen istila edildiğini'], 'Dairesel dansta arı küçük çemberler çizer; bu dans yakınlarda besin olduğunu ve çiçek kokusunu bildirir fakat Güneş\'e göre spesifik bir açısal yön vermez.'),
  ('Deney amacıyla kovan peteği düşey konumdan yatay konuma getirilir ve arıların gökyüzünü/Güneş\'i görmesine izin verilirse öncü arılar sallanma dansını nasıl yönlendirir?', 'Yerçekimi ipucu ortadan kalktığı için düz sallanma koşusunu doğrudan besin kaynağının gerçek yönüne doğru yaparlar', ['Yatay yüzeyde yön bulamadıkları için kanatlarını kapatıp dans etmeyi tamamen bırakırlar', 'Besin kaynağının yönünden bağımsız olarak sürekli kuzey kutbuna doğru düz koşu yaparlar', 'Yalnızca geceleri yıldızların yansımasını bekleyerek petek altında ters asılı dans ederler'], 'Yatay petekte yerçekimi vektörü yön referansı olamaz; gökyüzü veya polarize ışık görülüyorsa arı doğrudan besine bakan gerçek pusula yönünde sallanma koşusu yapar.'),
  ('Bal arılarının çiçekleri bulurken insan gözünün göremediği hangi ışık dalga boyunu görebilmeleri, taç yapraklar üzerindeki "nektar kılavuzlarını" (bal özü işaretlerini) seçmelerini sağlar?', 'Morötesi (ultraviyole) ışık', ['Kızılötesi (infrared) ışık', 'Mikrodalga ışınımı', 'Radyo dalgaları'], 'Karl von Frisch ve sonraki araştırmacılar arıların kırmızıya duyarsız olduğunu ancak morötesi (UV), mavi ve yeşil dalga boylarını görerek UV nektar kılavuzlarını izlediğini göstermiştir.'),
  ('Mağaralarda yaşayan yağ kuşları (Steatornis caripensis) ve bazı mağara ebabil türlerinin (Aerodramus) yarasalardan farklı bir ekolokasyon ses özelliği göstermesinin temel farkı nedir?', 'Kullandıkları tıkırtı seslerinin ultrasonik değil, insan kulağının da rahatça duyabildiği işitilebilir frekans aralığında olması', ['Ses dalgalarını ağız veya gırtlak yerine kuyruk tüylerini birbirine sürterek üretmeleri', 'Yalnızca suyun altına daldıklarında balık avlamak amacıyla ekolokasyon yapabilmeleri', 'Yankıları kulaklarıyla değil, gagalarının ucundaki ısıya duyarlı çukurcuklarla algılamaları'], 'Ekolokasyon yapan nadir kuşlardan yağ kuşları ve mağara salanganları (ebabilgiller), 1–10 kHz aralığında insan kulağının duyabildiği tıkırtılar çıkararak karanlık mağaralarda uçar.'),
  ('Bazı karasal böcekçil memelilerin (örneğin sivri fareler - Sorex ve Madagaskar tenrekleri) karanlıkta veya yaprak döküntüsü altında çevrelerini yoklamak için kullandıkları akustik yöntem nedir?', 'Kısa ve yüksek perdeli tiz gıcırtılar/tıkırtılar çıkararak basit düzeyde ekolokasyon yapmaları', ['Toprağa arka ayaklarıyla vurarak kilometrelerce uzağa giden deprem dalgaları üretmeleri', 'Kuyruk uçlarındaki çıngırak halkalarını sallayarak avlarını hipnotize etmeleri', 'Kulak kepçelerini birbirine çarparak infrasonik (düşük frekanslı) uğultular yaymaları'], 'Yarasalar ve dişli balinalar kadar gelişmiş olmasa da sivri fareler (Soricidae) ve tenrekler yakın çevredeki engelleri ve geçitleri yüksek frekanslı seslerin yankısıyla yoklar.'),
  ('Karıncaların aynı koloniden olan yuva arkadaşlarını yabancı koloni bireylerinden saniyeler içinde ayırt edip yabancılara saldırmasını sağlayan kimyasal kimlik nerede taşınır?', 'Dış iskelet (kütikül) yüzeyini kaplayan mumsu hidrokarbon tabakasındaki koloniye özgü koku karışımında', ['Kanat damarlarının içinde dolaşan kırmızı renkli hemoglobin pigmentlerinde', 'Bileşik gözlerin yüzeyindeki altıgen merceklerin ışık kırma derecesinde', 'Arka bacak eklemlerinden yürürken çıkan tıkırtı seslerinin frekansında'], 'Karıncalar birbirlerine antenleriyle dokunduklarında vücut yüzeyindeki kütiküler hidrokarbon (CHC) profilini koklayarak "bizden / yabancı" ayrımı yaparlar.'),
  ('Erkek köpeklerin, kurtların veya kedigillerin yaşam alanlarındaki ağaç gövdelerine ve kayalara idrar ya da bez salgıları bırakarak sınır belirlemesi hangi iletişim kanalına örnektir?', 'Kimyasal (feromonal/koku) iletişim', ['Akustik (sesli) iletişim', 'Dokunsal (taktil) iletişim', 'Elektriksel iletişim'], 'İdrar ve koku bezi salgılarıyla yapılan bölge işaretleme; bireyin eşeyini, üreme durumunu ve alan sahipliğini sahibi orada yokken bile kalıcı olarak bildiren kimyasal iletişimdir.'),
  ('Bir yılanın dilini sık sık dışarı çıkarıp havada salladıktan sonra ağzının içine geri çekmesinin yön bulma ve av takibindeki işlevi nedir?', 'Çatallı dil uçlarıyla sağdan ve soldan topladığı koku/feromon moleküllerini damaktaki Jacobson organına taşıyarak avın iz yönünü belirlemek', ['Havadaki ses dalgalarının basıncını dil yüzeyinde ölçerek avın çıkardığı ekolokasyon yankısını dinlemek', 'Vücut sıcaklığını düşürmek amacıyla tıpkı köpeklerdeki gibi terleme yerine dilinden su buharlaştırmak', 'Avına saldırmadan önce zehir dişlerinin ucundaki kanalları tükürükle temizleyip keskinleştirmek'], 'Yılanın dilinin iki ucu kokuyu iki ayrı noktadan örnekler (stereolfaksiyon); bu sayede Jacobson organı kokunun hangi tarafta daha yoğun olduğunu saptar.'),
  ('Çöl karıncalarının (Cataglyphis) kavurucu sıcakta feromon izlerinin hızla buharlaştığı kum yüzeyinde besin ararken zikzaklar çizip dolaştıktan sonra yuvalarına dümdüz bir çizgide geri dönebilmelerini sağlayan navigasyon yöntemi hangisidir?', 'Adım sayma (odometri) ve gökyüzü polarizasyon/Güneş pusulasını birleştiren "yol tümleştirme"', ['Kumun altındaki yer altı sularının çıkardığı ekolokasyon yankılarını dinleme', 'Geceleri çıkan kutup yıldızının kum taneleri üzerindeki yansımasını takip etme', 'Yuva girişinde bekleyen kraliçe karıncanın yaydığı kızılötesi ısı ışınlarını izleme'], 'Sahra çöl karıncaları (Cataglyphis) bacaklarındaki içsel adım sayacıyla mesafeyi, polarize UV ışık pusulasıyla yönleri sürekli toplayarak (yol tümleştirme) yuvaya kestirmeden döner.'),
  ('Ateş böceklerinin gece karanlığında karın uçlarındaki ışık organlarıyla türe özgü ritmik parlamalar üretmesi ile güvelerin eş bulması karşılaştırıldığında temel iletişim farkı nedir?', 'Ateş böcekleri eş bulmada ağırlıklı olarak görsel (biyolüminesans) sinyalleri, gece güveleri ise kimyasal (feromon) sinyalleri kullanır', ['Ateş böcekleri yalnızca ultrasonik ekolokasyonla, güveler ise düşük frekanslı su altı sesleriyle eş bulur', 'Her iki böcek grubu da eşlerini yalnızca Dünya\'nın manyetik alan çizgilerini takip ederek bulur', 'Ateş böcekleri koku bırakarak yerde yürürken, güveler kanat uçlarından mavi lazer ışığı yayarak uçar'], 'Her iki grup da gece aktif böcekler olmasına rağmen ateş böcekleri (Lampyridae) türe özgü flaş kodlarıyla görsel, güveler ise uçucu eşey feromonlarıyla kimyasal iletişim kurar.'),
  ('Bir canlının bulunduğu doğal ortamın renk ve desenlerine uyum sağlayarak yırtıcılardan gizlenmesine biyolojide hangi ad verilir?', 'Kriptik renklenme', ['Aposematik uyarı renklenmesi', 'Müller tipi karşılıklı mimikri', 'Ototomi yoluyla uzuv bırakma'], 'Kriptik renklenme (kamuflaj), canlının arka planla bütünleşerek fark edilmesini zorlaştıran gizlenme adaptasyonudur.'),
  ('Bukalemun ve mürekkep balığı gibi canlıların derisinde bulunan, renk değişimini sağlayan pigment keseciklerine ne ad verilir?', 'Kromatofor', ['Nematosist', 'Fotoreseptör', 'Statokist'], 'Kromatoforlar, içerdikleri renk pigmentlerini yayıp toplayarak veya ışığı yansıtarak deri renginin değişmesini sağlayan özel hücrelerdir.'),
  ('Kutup tilkisinin kışın kar beyazı, yazın ise kahverengi-gri kürke sahip olmasının temel evrimsel avantajı nedir?', 'Mevsimsel arka plan değişimine uyum sağlayarak hem avından hem yırtıcısından gizlenmek', ['Kış aylarında güneş ışınlarını daha fazla soğurarak vücut sıcaklığını hızla artırmak', 'Üreme döneminde karşı cinse parlak uyarı sinyalleri göndererek kur davranışını güçlendirmek', 'Zehirli bir tür olduğunu avcı kuşlara ilan ederek saldırıları tamamen engellemek'], 'Mevsimsel tüy değişimi, kutup tilkisinin karlı kış ortamında ve taşlı-topraklı yaz tundrasında kriptik kalmasını sağlar.'),
  ('Zehirli, kötü tatlı veya tehlikeli canlıların sarı, kırmızı ve siyah gibi parlak renklerle avcıları uyarmasına ne ad verilir?', 'Aposematizm', ['Kriyobiyoz', 'Ototomi', 'mutualizm'], 'Aposematizm (uyarı renklenmesi), tehlikeli avların avcılar tarafından kolayca tanınıp hatırlanmasını sağlayan savunma stratejisidir.'),
  ('Bir kertenkelenin yırtıcı tarafından yakalandığında kuyruğunu istemli olarak bırakıp kaçması olayına ne denir?', 'Ototomi', ['Metamorfoz', 'Rejenerasyon', 'Partenogenez'], 'Ototomi, tehlike anında canlının vücudunun bir parçasını (örneğin kuyruk veya bacak) kendiliğinden koparıp bırakmasıdır.'),
  ('Zehirli ok kurbağalarının ormanda yaprakların arasında saklanmak yerine parlak mavi veya sarı renklerle açıkça dolaşabilmesinin nedeni nedir?', 'Avcıların bu parlak renkleri zehir ve kötü tat ile ilişkilendirip saldırıdan kaçınması', ['Parlak renklerin orman zeminindeki yeşil yapraklarla kusursuz bir kamuflaj oluşturması', 'Yüksek nemli ortamlarda deri solunumunun yalnızca açık ve parlak pigmentlerle yapılabilmesi', 'Kurbağanın tehlike anında bacaklarını ototomi ile bırakıp hızla uzaklaşabilmesi'], 'Aposematik canlılar gizlenmeye ihtiyaç duymaz; aksine avcıların kendilerini uzaktan tanıyıp hataen ısırmamasını hedefler.'),
  ('Ahtapotların dokusunun sadece rengini değil, pürüzlülüğünü ve dikenli yapısını da kayaya veya mercana benzetmesini sağlayan deri çıkıntılarına ne denir?', 'Papilla', ['Kirpikcik', 'Antenül', 'Trakeol'], 'Kafadanbacaklılar derilerindeki kaslı papillaları kabartıp düzleştirerek 3 boyutlu doku kamuflajı sağlarlar.'),
  ('Uğur böceğinin kırmızı kabuğu üzerindeki siyah benekler ve tehlike anında eklemlerinden salgıladığı sarı kötü kokulu sıvı hangi savunma ikilisine örnektir?', 'Aposematik renklenme ve kimyasal savunma', ['Bates mimikrisi ve kuyruk bırakma', 'Mevsimsel kamuflaj ve ters gölgeleme', 'Maskeleme ve elektriksel şok üretimi'], 'Uğur böceği hem alkaloit içeren kötü tatlı hemolenf salgılar (refleks kanaması) hem de kırmızı-siyah uyarı renkleriyle bunu ilan eder.'),
  ('Çubuk böceklerinin (Phasmatodea) ince uzun gövdeleri ve bacak yapılarıyla ağaç dallarına benzemesi avcıya karşı hangi aşamada koruma sağlar?', 'Saldırı başlamadan önce, avcının böceği besin olarak tanımasını engelleyerek (birincil savunma)', ['Avcı böceği ısırdıktan sonra ağzında acı bir tat bırakarak (ikincil savunma)', 'Avcının midesinde sindirilmeye direnç gösterip canlı olarak dışarı çıkarak', 'Kopmuş bacaklarının avcının boğazına takılıp boğulmasına yol açarak'], 'Avcı ile karşılaşma veya fark edilme olasılığını düşüren kamuflaj ve maskeleme "birincil savunma" mekanizmalarıdır.'),
  ('Bal arısı ve eşek arısının sarı-siyah şeritli gövde desenine sahip olması doğada hangi temel görsel mesajı taşır?', 'İğneli ve acı verici savunmaya sahip olduklarını gösteren uyarı renklenmesi', ['Çiçeklerin sarı polenleri arasında tamamen görünmez olmalarını sağlayan kriptik kamuflaj', 'Kış uykusuna yatmadan önce güneş enerjisini depolamaya yarayan termal adaptasyon', 'Kuşların dikkatini çekerek arı kovanındaki fazla balları tüketmelerini sağlama'], 'Sarı-siyah yüksek kontrastlı şeritler doğada en yaygın aposematik uyarı kalıplarından biridir.'),
  ('Dil balığı ve pisi balığı gibi yassı balıkların yaşam biçimine uygun olarak geliştirdiği en belirgin korunma adaptasyonu hangisidir?', 'Deniz tabanındaki kum ve çakıl desenini derilerinde taklit ederek zemine gömülmeleri', ['Su yüzeyine sıçrayarak parlak kırmızı yüzgeçleriyle kuşları uyarmaları', 'Tehlike anında kuyruk yüzgeçlerini koparıp bırakarak hızla uzaklaşmaları', 'Zehirli denizanalarının dokunaçlarını sırtlarında taşıyarak simbiyoz kurmaları'], 'Yassı balıklar görsel sistemlerinden gelen bilgiyle kumlu ya da çakıllı tabanın benek boyutunu derilerinde kriptik olarak kopyalar.'),
  ('Ateş semenderinin (Salamandra salamandra) parlak siyah zemin üzerinde sarı lekelere sahip olması avcılara hangi mesajı verir?', 'Derisindeki bezlerden tahriş edici ve nörotoksik salgılar ürettiğini, yenmeye uygun olmadığını', ['Orman zeminindeki kuru meşe yaprakları arasında tamamen görünmez olduğunu', 'Çok hızlı koşabildiği için yakalanmasının boşuna enerji kaybı olacağını', 'Kuyruğunu bıraktığında zehrinin tamamını kaybedip zararsız hale geleceğini'], 'Ateş semenderi derisinden samandarin adlı toksik alkaloit salgılar; siyah-sarı renklenme klasik aposematik uyarıdır.'),
  ('Bazı yengeç türlerinin (süslü yengeçler) deniz süngerlerini, yosunları veya kabuk parçalarını koparıp kendi kabuklarına tutturarak gizlenmesine ne ad verilir?', 'Kendini süsleme / dekoratör kamuflajı', ['Aposematik renk değişimi', 'Mevsimsel tüy dökümü', 'Fizyolojik kromatofor yayılımı'], 'Dekoratör yengeçler (Majidae vb.) kabuklarındaki kancalı kıllara çevredeki organizmaları tutturarak hem görsel hem kimyasal kamuflaj sağlar.'),
  ('Baykuşların ağaç kabuğu desenine sahip tüyleriyle gündüzleri ağaç gövdesinde gözlerini kısarak hareketsiz durması hangi korunma yöntemidir?', 'Kriptik kamuflaj', ['Bates mimikrisi', 'Aposematizm', 'Ototomi'], 'Tüy deseninin ağaç kabuğuyla bütünleşmesi ve duruşun buna eşlik etmesi tipik bir görsel kriptik kamuflajdır.'),
  ('Çölde yaşayan boynuzlu engerek yılanının kum renginde olması ve vücudunu yanlara sallayarak kuma gömmesi ona hangi çifte avantajı sağlar?', 'Hem yırtıcı kuşlardan korunur hem de avı olan kemirgenlere fark edilmeden pusu kurar', ['Hem zehirli olduğunu uzaktan belli eder hem de kış uykusu için derin tüneller kazar', 'Hem vücut rengini maviye çevirir hem de kuyruğunu bırakarak avcıyı şaşırtır', 'Hem su kaybını derisinden terleyerek artırır hem de diğer yılanlarla Müller mimikrisi kurar'], 'Hem avcı hem av konumundaki mezopredatörlerde kamuflaj, yukarıdaki yırtıcıdan korunma ve aşağıdaki ava pusu kurma (agresif/kriptik gizlenme) sağlar.'),
  ('Kirpi balığının tehlike anında su yutarak şişmesi, dikenlerini dikleştirmesi ve dokularında tetrodotoksin taşıması hangi genel biyolojik amaca hizmet eder?', 'Yırtıcıdan korunma ve yutulmayı caydırma', ['Üreme göçünde okyanus akıntılarıyla hızlanma', 'Avlarını elektrik şokuyla uzaktan bayıltma', 'Deniz tabanındaki kumlara kriptik olarak gömülme'], 'Kirpi balığı hem mekanik (şişme ve dikenler) hem de güçlü kimyasal (tetrodotoksin) savunma ile yırtıcıları caydırır.'),
  ('Tembel hayvanın (Bradypus) çok yavaş hareket etmesi ve tüylerinin arasında yeşil alglerin (yosunların) büyümesi ona yağmur ormanında nasıl bir fayda sağlar?', 'Ağaç taç katmanında yeşil yapraklı ve yosunlu dallar arasında görsel kamuflaj sağlar', ['Tüylerindeki alglerin zehir üretmesiyle kaplanlara karşı aposematik uyarı oluşturur', 'Alglerin ağırlığı sayesinde tehlike anında daldan hızla yere atlayıp koşmasını kolaylaştırır', 'Kış aylarında tüylerinin kar beyazına dönmesini hızlandıran hormonlar salgılar'], 'Yavaş hareket avcıların hareket algısını tetiklemez; tüylerdeki simbiyotik yeşil algler de ağaç tepesinde mükemmel kriptik uyum yaratır.'),
  ('Peygamberdevesi türlerinden Hymenopus coronatus\'un pembe-beyaz renkleri ve taç yaprağına benzeyen yassı bacaklarıyla orkide çiçeğine tıpatıp benzemesi ne sağlar?', 'Hem kuş gibi avcılardan gizlenir hem de tozlaşmaya gelen böcekleri kendine çekerek avlar', ['Zehirli orkide özsuyu salgıladığını otçul memelilere parlak renklerle duyurur', 'Mevsim kışa döndüğünde yapraklarını dökerek kar üzerinde beyaz kürk oluşturur', 'Tehlike anında çiçek görünümündeki tüm bacaklarını bırakıp uçarak kaçar'], 'Orkide peygamberdevesi hem korunma kamuflajı hem de avını tuzağa çeken agresif (çekici) mimikri/kamuflaj sergiler.'),
  ('Çita yavrularının sırtında bulunan uzun gümüşi-beyaz tüy yelesinin (manto), bal porsuğuna benzetilmesinin yanı sıra kuru savan otları arasında sağladığı diğer temel fayda nedir?', 'Yüksek otların arasında yavrunun silüetini bozarak sırtlan ve aslanlardan gizlenmesine (kamuflaj) yardımcı olması', ['Yavru çitanın yetişkinlerden daha hızlı koşmasını sağlayan aerodinamik rüzgâr kanadı oluşturması', 'Güneş ışığını mercek gibi toplayarak yavrunun kemik gelişimini iki kat hızlandırması', 'Tehlike anında bu tüy tabakasını tek parça halinde sırtından atıp kaçmasını sağlaması'], 'Çita yavrularındaki manto hem kuru otlarla kriptik uyum sağlar hem de saldırgan bal porsuğunu andırarak (mimikri hipotezi) avcıları caydırır.'),
  ('Deniz kaplumbağası yavrularının yumurtadan genellikle gece vakti ve yüzlerce yavru aynı anda çıkmasının yırtıcılardan korunmadaki karşılığı nedir?', 'Avcı doygunluğu (predator satiation) yaratarak bireysel yakalanma olasılığını düşürmek', ['Karanlıkta parlak aposematik kabuk renklerini yengeçlere daha net göstermek', 'Hep birlikte birleşerek dev bir köpekbalığı silüeti taklit etmek', 'Yumurtadan çıkar çıkmaz ön yüzgeçlerini ototomi ile kumsalda bırakmak'], 'Çok sayıda avın eşzamanlı ortaya çıkması sınırlı sayıdaki avcıyı kısa sürede doyurur (avcı doygunluğu), böylece birey başına hayatta kalma şansı artar.'),
  ('Opossumun (keseli sıçan) ve bazı yılanların yırtıcıdan kaçamayacak duruma geldiklerinde hareketsiz kalıp ölü gibi görünmelerine ne ad verilir?', 'Tanatoz (ölü taklidi)', ['Ototomi (uzuv bırakma)', 'Aposematizm (uyarı renklenmesi)', 'Kriyojenez (dondurma)'], 'Tanatoz (tonic immobility / ölü taklidi), yalnızca canlı ve hareketli avlara saldıran yırtıcıların ilgisini kaybettiren davranışsal bir savunmadır.'),
  ('Kar leoparının boz-beyaz kürkü üzerinde koyu halkalı rozet lekeler taşıması Orta Asya\'nın yüksek dağlarında nasıl bir işlev görür?', 'Karlı, kayalık ve gölgeli uçurum yamaçlarında arka planla bütünleşerek avı olan dağ keçilerine görünmeden yaklaşmasını sağlar', ['Diğer yırtıcılara zehirli pençelere sahip olduğunu gösteren aposematik bir uyarı görevi yapar', 'Yaz aylarında kürkünün tamamen yemyeşil çimen rengine dönüşmesini başlatır', 'Tehlike anında uzun kuyruğunu kertenkeleler gibi koparıp bırakmasına yardımcı olur'], 'Boz-beyaz zemin ve parçalı rozetler, kar yamaları ile kırık kaya gölgelerinden oluşan yüksek irtifa habitatında yıkıcı/kriptik kamuflaj sunar.'),
  ('Ağaç kurbağasının yeşil yaprak üzerinde yeşil görünmesi hangi temel korunma kategorisinde değerlendirilir?', 'Arka plan eşleşmesi', ['Müller mimikrisi', 'Bates mimikrisi', 'Uzuv ototomisi'], 'Canlının üzerinde bulunduğu yaprağın rengiyle birebir uyumlu olması en temel kriptik arka plan eşleşmesidir.'),
  ('Kutup ayısının kürk kıllarının aslında renksiz ve içi boş tüpler olmasına rağmen hayvanın karlı ortamda beyaz görünmesi nasıl gerçekleşir?', 'İçi hava dolu şeffaf kılların güneş ışığını her yöne saçıp yansıtmasıyla beyaz algılanması', ['Ayının her sabah karların içinde yuvarlanarak kürkünü kar kristalleriyle kaplamasıyla', 'Derisinin bembeyaz olması ve şeffaf kılların alttaki beyaz deriyi göstermesiyle', 'Yediği fok yağlarının kılların içinde beyaz kireç tabakasına dönüşmesiyle'], 'Kutup ayısının derisi aslında siyahtır (ısıyı tutmak için); ancak pigment içermeyen içi boş keratin kıllar ışığı saçarak karla uyumlu beyaz kamuflaj sağlar.'),
  ('Memelilerin dondurucu soğuk ve besin kıtlığı olan kış aylarında vücut sıcaklıklarını ve metabolizma hızlarını düşürerek geçirdikleri derin uyuşukluk evresine ne ad verilir?', 'Hibernasyon', ['Estivasyon süreci', 'Murmuration olayı', 'Fotoperiyodizm tepkisi'], 'Kış uykusu biyolojide hibernasyon olarak adlandırılır ve enerji tasarrufu sağlar.'),
  ('Aşırı sıcak ve kurak geçen yaz aylarında su kaybını önlemek amacıyla bazı kurbağa ve salyangoz türlerinin girdiği uzun süreli uyuşukluk durumuna ne denir?', 'Estivasyon', ['Hibernasyon evresi', 'Günlük torpor hali', 'Vernalizasyon tepkisi'], 'Kuraklık ve aşırı sıcak kaynaklı yaz uykusuna estivasyon adı verilir.'),
  ('Kış uykusuna yatan memelilerde titreme olmaksızın doğrudan ısı üretmekle görevli olan ve bol miktarda mitokondri içeren özelleşmiş doku hangisidir?', 'Kahverengi yağ dokusu', ['Beyaz yağ dokusu', 'Çizgili kas dokusu', 'Hiyalin kıkırdak dokusu'], 'Kahverengi yağ dokusu, termogenin proteini sayesinde ATP yerine doğrudan ısı üretir.'),
  ('Gece boyunca açlıktan ve soğuktan ölmemek için metabolizma hızını %90\'a varan oranda düşürerek günlük torpora giren en bilinen kuş grubu hangisidir?', 'Kolibriler', ['Albatroslar', 'İmparator penguenleri', 'Kıyı sumruları'], 'Yüksek metabolizmalı kolibriler geceleri enerji korumak için günlük torpora girer.'),
  ('Kara salyangozlarının kavurucu yaz sıcaklarında kabuklarının ağzını "epifragma" adı verilen kuru mukus ve kalsiyum karbonat tabakasıyla kapatmasının temel amacı nedir?', 'Buharlaşma yoluyla gerçekleşecek ölümcül su kaybını en aza indirmek', ['Kabuk içerisine güneş ışığı girmesini sağlayarak fotosentezi hızlandırmak', 'Avcı kuşların kabuğu gagalarıyla kırmasını imkânsız hâle getirmek', 'Topraktaki fazla yağmur suyunun solungaç boşluğuna dolmasını engellemek'], 'Epifragma zarı estivasyon süresince salyangozun nemini korur.'),
  ('Kış uykusuna hazırlanan bir yer sincabının sonbahar aylarında aşırı beslenerek vücut kütlesini neredeyse iki katına çıkarması davranışına ne ad verilir?', 'Hiperfaji', ['Otofaji', 'Anoreksiya', 'Fototaksi'], 'Göç ve kış uykusu öncesi aşırı beslenerek yağ depolama evresine hiperfaji denir.'),
  ('Kış uykusundaki memelilerin kahverengi yağ dokusuna koyu rengini veren temel hücresel yapı aşağıdakilerden hangisidir?', 'Demir içeren sitokrom pigmentlerince zengin yoğun mitokondriler ve sık kılcal damar ağı', ['Güneşin zararlı morötesi ışınlarını emmek üzere sentezlenen yoğun melanin kesecikleri', 'Fotosentez tepkimelerini karanlıkta sürdürmeye yarayan klorofil a ve karotenoidler', 'Kemik iliğinden yağ dokusuna göç ederek orada parçalanan yaşlı trombosit kümeleri'], 'Mitokondrilerdeki sitokromların içerdiği demir atomları ve yoğun damarlanma dokuya kahverengi rengini verir.'),
  ('Bir kolibrinin gece girdiği günlük torpor durumundan sabah güneş doğmadan hemen önce çıkabilmesi için gereken ilk ısı çoğunlukla nasıl üretilir?', 'Şiddetli kas titremesi ve yağ oksidasyonunun hızlandırılmasıyla içsel (endojen) olarak üretilir', ['Güneş ışınlarının doğrudan tüysüz deriye çarpmasıyla dışsal (ekzojen) olarak kazanılır', 'Yuvasına önceden biriktirdiği sıcak taşların üzerine yatarak iletim yoluyla alınır', 'Çiçek nektarının midede mayalanarak alkol fermantasyonu yapmasıyla kendiliğinden oluşur'], 'Kolibriler sabah güneş doğmadan önce kas titremesi (shivering thermogenesis) ile kendi vücutlarını ısıtarak uyanırlar.'),
  ('Soğukkanlı (ektoterm) sürüngen ve amfibilerin kış aylarında metabolizmalarını yavaşlatarak girdikleri soğuk uyuşukluğu durumuna özel olarak hangi terim verilir?', 'Brumasyon', ['Murmuration', 'Navigasyon', 'Ekolokasyon'], 'Sürüngen ve amfibilerdeki kış uyuşukluğu fizyolojik olarak memeli hibernasyonundan ayrılarak brumasyon diye adlandırılır.'),
  ('Böceklerin olumsuz mevsim koşullarını (kış soğuğu veya yaz kuraklığı) aşmak için gelişimlerini genetik ve hormonal kontrolle geçici olarak durdurdukları evreye ne denir?', 'Diyapoz', ['Metamorfoz', 'Partenogenez', 'Rejenerasyon'], 'Eklembacaklılarda ve bazı omurgasızlarda çevresel sinyallerle önceden programlanan gelişim durmasına diyapoz denir.'),
  ('Çöl ortamında yaşayan kanguru fareleri ve cep farelerinin tohum bulamadıkları kurak veya soğuk dönemlerde yuvalarında sergiledikleri enerji tasarrufu davranışı hangisidir?', 'Torpor ve dönemsel uyuşukluk', ['binlerce kilometrelik kıtalararası göç', 'Deri solunumuyla su altında kışlama', 'Sürü hâlinde murmuration uçuşu'], 'Cep fareleri ve bazı çöl kemirgenleri besin kıtlığında metabolizmalarını düşürerek torpora girer.'),
  ('Kış uykusundaki bir memelinin solunum alışverişinde periyodik olarak dakikalarca nefes almadan beklemesi (apne) ve ardından birkaç hızlı nefes alması durumu neyin göstergesidir?', 'Azalan oksijen ihtiyacı ve değişen karbondioksit eşiğine bağlı normal torpor solunum düzeninin', ['Akciğer bronşlarının buz kristalleriyle tamamen tıkanarak hayvanın boğulmak üzere olduğunun', 'Diyafram kasının sinir bağlantısının kalıcı olarak koptuğunun ve solunumun bittiğinin', 'Hayvanın rüya evresinde koştuğunu sanarak hiperventilasyon geçirdiğinin'], 'Derin hibernasyonda Cheyne-Stokes benzeri aralıklı (epizodik) solunum ve uzun apne periyotları fizyolojik olarak normaldir.'),
  ('Kuzey Kutbu\'ndaki üreme alanları ile Güney Kutbu (Antarktika) kıyıları arasında her yıl gidiş-dönüş uçarak hayvanlar âleminin en uzun mesafeli göç rekorunu elinde tutan kuş türü hangisidir?', 'Kuzey sumrusu (Kıyı sumrusu - Sterna paradisaea)', ['İmparator pengueni (Aptenodytes forsteri)', 'Gezgin albatros (Diomedea exulans)', 'Bayağı leylek (Ciconia ciconia)'], 'Kuzey (kıyı) sumrusu Arktik ve Antarktik bölgeler arasında yılda 70.000-90.000 km\'ye varan göçüyle rekortmendir.'),
  ('Kuzey Amerika\'dan Meksika\'nın orta kesimlerindeki oyamel göknarı ormanlarına binlerce kilometre göç eden ve bu döngüyü birden fazla nesilde tamamlayan ünlü böcek türü hangisidir?', 'Kral kelebeği (Danaus plexippus)', ['İpek böceği güvesi (Bombyx mori)', 'Yedi noktalı uğur böceği (Coccinella septempunctata)', 'Avrupa bal arısı (Apis mellifera)'], 'Kral kelebekleri Kanada/ABD ile Meksika arasında çok kuşaklı destansı bir göç gerçekleştirir.'),
  ('Kral kelebeği tırtıllarının üzerinde beslendiği ve içindeki kardiyak glikozit (kardenolid) zehirlerini bünyesine alarak avcı kuşlara karşı korunma sağladığı tek konak bitki cinsi hangisidir?', 'İpek otu (Asclepias)', ['Ökse otu (Viscum)', 'Isırgan otu (Urtica)', 'Çobanpüskülü (Ilex)'], 'Kral kelebeği larvaları yalnızca ipek otu (milkweed - Asclepias) türleriyle beslenir ve bu bitkinin zehrini depolar.'),
  ('Tatlı su nehirlerinde yumurtadan çıkıp büyümek için okyanusa göç eden, yıllar sonra üremek üzere koku hafızasıyla tam olarak doğduğu nehre geri dönen (anadrom) balık grubu hangisidir?', 'Somon balıkları', ['Avrupa yılan balıkları', 'Mercan kayalığı palyaço balıkları', 'Derin deniz fener balıkları'], 'Somonlar anadrom göç yapar; doğdukları akarsuyun kimyasal kokusunu (imprinting) hafızalarına kazıyarak üremek için geri dönerler.'),
  ('Karasal memeliler arasında Kuzey Amerika arktik tundralarında yılda yaklaşık 4.000-5.000 kilometreye varan en uzun mesafeli kara göçlerinden birini gerçekleştiren geyik türü hangisidir?', 'Ren geyiği (Karibu - Rangifer tarandus)', ['Kızıl geyik (Cervus elaphus)', 'Cüce misk geyiği (Moschus berezovskii)', 'Alageyik (Dama dama)'], 'Kuzey Amerika karibu (ren geyiği) sürüleri karasal memeliler arasındaki en uzun yıllık göç rekorlarını elinde tutar.'),
  ('Göç hazırlığındaki kafesli ötücü kuşların göç mevsimi geldiğinde geceleri tüneklerinde göç yönüne doğru zıplayıp kanat çırparak sergiledikleri içgüdüsel göç huzursuzluğuna bilim dilinde ne ad verilir?', 'Zugunruhe', ['Murmuration', 'Brumasyon', 'Ötrofikasyon'], 'Almanca kökenli "Zugunruhe" terimi, ornitolojide göçmen kuşların mevsimsel gece göç huzursuzluğunu ifade eder.'),
  ('Alaca sığırcıkların (Sturnus vulgaris) özellikle gün batımına yakın saatlerde binlerce bireyden oluşan dev bulutlar hâlinde gökyüzünde eş zamanlı kıvrılıp dalgalanarak sergiledikleri büyüleyici sürü uçuşuna ne ad verilir?', 'Murmuration', ['Hibernasyon', 'Ekolokasyon', 'Biyolüminesans'], 'Binlerce sığırcığın tek bir organizma gibi koordineli uçuş gösterisine murmuration denir.'),
  ('Kaz, turna ve pelikan gibi iri göçmen kuşların uzun uçuşlar sırasında gökyüzünde "V" harfi diziliminde uçmalarının sağladığı en önemli aerodinamik avantaj nedir?', 'Öndeki kuşun kanat ucunda oluşan yukarı yönlü hava girdabından (upwash) yararlanarak arkadaki kuşların enerji tasarrufu yapması', ['En arkadaki kuşların rüzgârı tamamen keserek en öndeki lider kuşu arkadan ileriye doğru itmesi', 'Sürünün gökyüzünde dev bir ok işareti oluşturarak yerdeki diğer kuşlara kuzey yönünü göstermesi', 'Kanatların birbirine çarpmasıyla oluşan statik elektriğin kuşların tüylerini sıcak tutması'], 'Öndeki kuşun kanat ucu vorteksi kanat dışında yükselen bir hava akımı yaratır; arkadaki kuş kanadını bu bölgeye yerleştirerek %10-20\'den fazla enerji kazanır.'),
  ('Balıkların tek bir merkezî lider olmaksızın aynı yönde, eşit aralıklarla ve eş zamanlı yüzerek oluşturdukları yüksek düzeyde koordineli sürü davranışına ichtiyolojide hangi özel ad verilir?', 'Polarize sürüleşme (Schooling)', ['Gevşek kümelenme (Shoaling)', 'Bölge savunması (Territoriality)', 'Kuluçka parazitliği (Brood parasitism)'], 'Balıkların rastgele bir arada bulunmasına shoaling, senkronize ve paralel yüzmelerine ise schooling (polarize sürüleşme) denir.'),
  ('Kış aylarında binlerce sığırcığın gün batımında murmuration yaptıktan sonra aynı sazlıkta veya ağaçlıkta birbirine yakın tünemesinin sağladığı iki temel yarar nedir?', 'Avcılara karşı erken uyarı/güvenlik sağlaması ve gece soğuğunda mikroiklim oluşturarak ısı kaybını azaltması', ['Sazlıkların köklerini kemirerek kış uykusuna yatacak çamur tünelleri kazmayı kolaylaştırması', 'Gece boyunca birbirlerinin tüylerini yolup yiyerek protein ihtiyacını karşılaması', 'Sabah doğacak Güneş\'in yönünü tartışarak yeni bir kıtaya göç kararı oylaması'], 'Toplu tüneme (communal roosting) hem termoregülasyon avantajı hem de çok göz etkisiyle avcı güvenliği ve besin alanı bilgi paylaşımı sağlar.'),
  ('Kuzey Kutup Bölgesi ile Antarktika arasında her yıl gidiş-dönüş toplamda en uzun göç yolculuğunu gerçekleştiren kuş türü hangisidir?', 'Kutup sumrusu', ['Kızıl gerdanlı dalgıç kuşu', 'Büyük kara sırtlı martı', 'Ak başlı deniz kartalı'], 'Kutup sumrusu (Sterna paradisaea), her yıl kutuptan kutba yaklaşık 70.000-90.000 kilometrelik gidiş-dönüş göçüyle bilinen en uzun göç rotasını izler.'),
  ('Hayvanların kış mevsimindeki soğuk ve besin kıtlığı koşullarına dayanmak için metabolizma hızlarını ve vücut sıcaklıklarını uzun süreli olarak düşürdükleri uyku durumuna ne ad verilir?', 'Hibernasyon', ['Fotoperiyodizm', 'Termoregülasyon', 'Homeostatik denge'], 'Hibernasyon (kış uykusu), metabolizmanın, kalp atım hızının ve solunumun belirgin biçimde yavaşladığı uzun süreli enerji tasarrufu evresidir.'),
  ('Sıcak ve kurak yaz aylarında çöl kaplumbağaları, bazı kara salyangozları ve akciğerli balıklar gibi canlıların su kaybını önlemek için girdikleri durgunluk durumuna ne ad verilir?', 'Estivasyon', ['Hibernasyon evresi', 'Kriyoproteksiyon', 'Endotermik ısınma'], 'Estivasyon (yaz uykusu), aşırı sıcaklık ve kuraklık dönemlerinde metabolizmanın yavaşlatılarak su ve enerji kaybının en aza indirildiği uyum stratejisidir.'),
  ('Bir canlının şekil ve renk bakımından yaşadığı doğal ortama uyum sağlayarak avcılardan veya avlarından gizlenmesini sağlayan kamuflaj biçimine ne ad verilir?', 'Kriptik renklenme', ['Aposematik uyarım', 'Biyolüminesans üretimi', 'Kemosentetik gizlenme'], 'Kriptik renklenme, canlının arka planın renk ve dokusuyla bütünleşerek görsel olarak fark edilmesini zorlaştıran kamuflaj stratejisidir.'),
  ('Zehirli ok kurbağalarının parlak mavi, sarı veya kırmızı renklere sahip olarak avcılara yenilmez olduklarını bildirmeleri hangi biyolojik terimle ifade edilir?', 'Aposematizm', ['Karşı gölgelenme', 'Bates mimikrisi', 'Kriptik renklenme'], 'Aposematizm (uyarı renklenmesi), zehirli veya tadı kötü türlerin avcılara tehlikeli olduklarını açıkça duyuran çarpıcı renk ve desenlere sahip olmasıdır.'),
  ('Ateş böceklerinin gece karanlığında eş bulmak amacıyla karın bölgelerinden soğuk ışık yaymaları hangi biyokimyasal olguya dayanır?', 'Biyolüminesans', ['Fotosentetik ışıma', 'Kızılötesi yansıma', 'Termal floresans'], 'Biyolüminesans, lüsiferin molekülünün lüsiferaz enzimi ve oksijen eşliğinde tepkimeye girerek canlı dokuda ısı üretmeden ışık yayması olayıdır.'),
  ('Yarasaların ve yunusların karanlıkta veya bulanık sularda yüksek frekanslı ses dalgaları yayarak yankıları üzerinden nesnelerin konumunu belirlemesine ne ad verilir?', 'Ekolokasyon', ['Manyetoresepsiyon', 'Elektrolokasyon', 'Kemosensör algı'], 'Ekolokasyon, yayılan ses dalgalarının nesnelere çarpıp geri dönme süresini ve frekans değişimini analiz ederek çevrenin haritalanmasını sağlar.'),
  ('Karıncaların besin kaynağından yuvaya dönerken yere bıraktıkları ve aynı türün diğer bireylerinin yolu bulmasını sağlayan kimyasal iletişim maddelerine ne ad verilir?', 'Feromon', ['Antikor proteini', 'Klorofil pigmenti', 'Nörotransmitter madde'], 'Feromonlar, aynı türün bireyleri arasında iz sürme, alarm verme, bölge işaretleme veya eş çekme gibi davranışları tetikleyen kimyasal sinyallerdir.'),
  ('Kuzey Afrika ve Orta Doğu\'da zaman zaman devasa sürüler oluşturarak uzun mesafeler kateden ve tarım alanlarına zarar verebilen göçmen böcek grubu hangisidir?', 'Çöl çekirgeleri', ['Yusufçuk larvaları', 'Ağustos böcekleri', 'Geyik böcekleri'], 'Çöl çekirgeleri (Schistocerca gregaria), nüfus yoğunluğu arttığında tekil fazdan sosyal sürü fazına geçerek rüzgârlarla binlerce kilometre göç edebilir.'),
  ('Dal böceklerinin ve yaprak böceklerinin yalnızca renk bakımından değil, vücut biçimi olarak da bitki parçalarına benzemeleri hangi stratejiye örnektir?', 'Maskeleme kamuflajı', ['Aposematik renklenme', 'Kış uykusu uyumu', 'Elektriksel gizlenme'], 'Maskeleme (masquerade), bir canlının çevredeki yenilmez bir nesneyi (dal, kuru yaprak, taş veya kuş dışkısı gibi) biçimsel olarak taklit etmesidir.'),
  ('Bazı kurbağa türlerinin yalnızca sırtları yeşil kamuflajlıyken tehlike anında bacak altlarındaki parlak turuncu veya kırmızı alanları aniden göstermesine ne ad verilir?', 'Flaş renklenme', ['Karşı gölgelenme', 'Kriptobiyozis geçişi', 'Mevsimsel diyapoz'], 'Flaş renklenme, normalde gizlenen canlının kaçış anında parlak bir renk gösterip sonra tekrar gizlenerek avcının kafasını karıştırmasıdır.'),
  ('Ateş böceklerinin farklı türlerinin aynı çayırda gece boyunca kendi eşlerini karıştırmadan bulmalarını sağlayan temel sinyal özelliği nedir?', 'Türe özgü ışık çakma ritmi ve süresi', ['Kanat çırpma sırasında çıkardıkları ıslık sesi', 'Ağaç kabuklarına sürttükleri renkli tozlar', 'Ay ışığını yansıtan metalik bacak yapıları'], 'Her ateş böceği türü, belirli bir süre, aralık ve uçuş hareketiyle eşleşen kendine özgü bir biyolüminesans kodu kullanarak eş seçimi yapar.'),
  ('Yarasaların karanlıkta avlarının yerini belirlemek için ağız veya burunlarından yaydıkları ses dalgaları insan kulağının işitme sınırına göre hangi aralıktadır?', 'Ultrasonik aralıkta', ['İnfrasonik aralıkta', 'İşitilebilir bas aralığında', 'Elektromanyetik aralıkta'], 'Yarasalar genellikle 20 kHz\'in üzerindeki yüksek frekanslı ultrasonik ses dalgaları yayarak küçük böceklerin bile ayrıntılı yankı görüntüsünü çıkarırlar.'),
  ('Yarasalar ve yunuslar dışında karanlık mağaralarda uçarken ekolokasyon kullanabilen kuş grubuna örnek olarak hangisi verilebilir?', 'Mağara kırlangıçları ve yağ kuşları', ['Büyük göçmen leylekler ve turnalar', 'Kutup martıları ve penguenler', 'Kızıl şahinler ve altın kartallar'], 'Güney Amerika yağ kuşu (Steatornis caripensis) ve Güneydoğu Asya mağara kırlangıçları karanlık mağara içlerinde işitilebilir tıklamalarla ekolokasyon yaparlar.'),
  ('İpek böceği (Bombyx mori) dişisinin erkekleri kilometrelerce uzaktan çekmek için salgıladığı ve tarihte kimyasal yapısı ilk kez tanımlanan eşey feromonu hangisidir?', 'Bombikol', ['Adrenalin hormonu', 'Klorofil pigmenti', 'Hemoglobin alt birimi'], '1959\'da izole edilen bombikol, erkek ipek böceklerinin tüy biçimli antenlerindeki alıcılarla birkaç molekül düzeyinde bile algılanabilen klasik bir eşey feromonudur.'),
  ('Erkek kambur balinaların üreme mevsiminde saatlerce sürdürebildikleri, okyanusta yüzlerce kilometre uzağa yayılabilen karmaşık ve tekrar eden ses dizilerine ne ad verilir?', 'Balina şarkısı', ['Sonar tıklaması', 'Yüzgeç şaklatması', 'Sismik uğultu'], 'Erkek kambur balinalar her üreme sezonunda popülasyon içinde kültürel olarak paylaşılan ve zamanla evrimleşen karmaşık melodik şarkılar söylerler.'),
  ('Denizlerdeki bazı balık ve ahtapotların tehlike anında vücutlarını çevrelerindeki kumun, çakılın veya mercanın rengine uydurmalarına genel olarak ne ad verilir?', 'Aktif kamuflaj', ['Aposematik gösteri', 'Bates tipi mimikri', 'Biyolüminesans çağrısı'], 'Aktif kamuflaj, canlının ortam değiştirdiğinde renk ve desenini hızlı sinirsel veya hormonal kontrolle yeni zemine uyarlayabilmesidir.'),
  ('Kokarcaların belirgin siyah-beyaz kürk deseni ve tehlike anında kuyruklarını kaldırarak ayaklarını yere vurmaları avcılara ne tür bir mesaj verir?', 'Kötü kokulu savunma salgısı püskürteceklerine dair aposematik uyarı', ['Çevredeki çalıların arasında görünmez olduklarına dair kriptik sinyal', 'Oyun oynamak veya çiftleşmek istediklerine dair sosyal davet', 'Yakında bir su kaynağı bulunduğuna dair yön işareti'], 'Kokarcanın yüksek kontrastlı siyah-beyaz deseni, kötü kokulu tiyol spreyini kullanmadan önce avcıları uyaran klasik bir memeli aposematizmi örneğidir.'),
  ('Ötücü kuşların son derece karmaşık ve çift sesli melodiler üretebilmesini sağlayan, soluk borusunun akciğerlere ayrıldığı noktada yer alan ses organı hangisidir?', 'Syrinks', ['Larinks kapağı', 'Timbal zarı', 'Kromatofor kesesi'], 'Kuşlarda gırtlak yerine soluk borusunun alt çatallanmasında bulunan syrinks, sağ ve sol kasların bağımsız kontrolüyle aynı anda iki farklı nota çıkarabilir.'),
  ('Bazı memelilerin (örneğin kurtlar, kediler ve geyikler) yaşadıkları bölge sınırlarını idrar, dışkı veya özel koku bezlerinin salgılarıyla işaretlemelerinin temel amacı nedir?', 'Bölge sahipliğini ve üreme durumunu diğer bireylere bildirmek', ['Topraktaki zararlı mantar sporlarını tamamen yok etmek', 'Yağmur sularının toprağa sızma hızını yavaşlatmak', 'Yalnızca göç yolundaki yıldızların yerini hatırlamak'], 'Koku işaretlemesi, bireylerin yüz yüze kavga etmeden bölge sınırlarını, kimliğini, sosyal statüsünü ve üreme hazır oluşunu kalıcı biçimde duyurmasını sağlar.'),
  ('Zehirli deniz salyangozları (nudibranch) gibi yumuşakçaların savunmasız yumuşak gövdelerine rağmen mercan resiflerinde son derece parlak ve göz alıcı renklere sahip olmaları neye örnektir?', 'Aposematizm', ['Karşı gölgelenme', 'Maskeleme kamuflajı', 'Mevsimsel kürk değişimi'], 'Pek çok deniz tavşanı, yedikleri sünger veya hidroidlerden aldıkları toksinleri ve yakıcı hücreleri dokularında biriktirir ve bunu parlak uyarı renkleriyle duyurur.'),
  ('Gece kelebeklerinin (güvelerin) pek çoğunun gündüzleri ağaç gövdelerinde kanatlarını kapalı tutup kahverengi-gri kabuk desenine uyması hangi temel hayatta kalma stratejisidir?', 'Kriptik kamuflaj', ['Aposematik gösteri', 'Agresif mimikri', 'Biyolüminesans iletişimi'], 'Gece aktif olan güveler gündüz dinlenirken görsel avlanan kuşlardan korunmak için ağaç kabuğunun renk ve çizgilerini kopyalayan kriptik kamuflajdan yararlanır.'),
  ('Yaban arılarının ve bal arılarının sokma organlarına ek olarak avcılara karşı ortaklaşa taşıdıkları uyarı renkleri hangi iki rengin yüksek kontrastlı birleşimidir?', 'Sarı ve siyah', ['Açık mavi ve beyaz', 'Soluk yeşil ve gri', 'Kahverengi ve bej'], 'Sarı ve siyah şeritler doğada böcekler aleminde en yaygın tanınan yüksek kontrastlı aposematik uyarı desenidir.'),
];
